pub mod uri_state {

    pub use crate::builder_types::{Set, Unset, IsSet, IsUnset};
    #[allow(unused)]
    use ::core::marker::PhantomData;
    mod sealed {
        pub trait Sealed {}
    }
    /// State trait tracking which required fields have been set
    pub trait State: sealed::Sealed {
        type Uri;
    }
    /// Empty state - all required fields are unset
    pub struct Empty(());
    impl sealed::Sealed for Empty {}
    impl State for Empty {
        type Uri = Unset;
    }
    ///State transition - sets the `uri` field to Set
    pub struct SetUri<S: State = Empty>(PhantomData<fn() -> S>);
    impl<S: State> sealed::Sealed for SetUri<S> {}
    impl<S: State> State for SetUri<S> {
        type Uri = Set<members::uri>;
    }
    /// Marker types for field names
    #[allow(non_camel_case_types)]
    pub mod members {
        ///Marker type for the `uri` field
        pub struct uri(());
    }
}

/// Builder for constructing an instance of this type
pub struct UriBuilder<'a, S: uri_state::State> {
    _state: PhantomData<fn() -> S>,
    _fields: (Option<S>, Option<UriValue<S>>),
    _lifetime: PhantomData<&'a ()>,
}

impl<'a> Uri<'a> {
    /// Create a new builder for this type
    pub fn new() -> UriBuilder<'a, uri_state::Empty> {
        UriBuilder::new()
    }
}

impl<'a> UriBuilder<'a, uri_state::Empty> {
    /// Create a new builder with all fields unset
    pub fn new() -> Self {
        UriBuilder {
            _state: PhantomData,
            _fields: (None, None),
            _lifetime: PhantomData,
        }
    }
}

impl<'a, S: uri_state::State> UriBuilder<'a, S> {
    /// Set the `name` field (optional)
    pub fn name(mut self, value: impl Into<Option<S>>) -> Self {
        self._fields.0 = value.into();
        self
    }
    /// Set the `name` field to an Option value (optional)
    pub fn maybe_name(mut self, value: Option<S>) -> Self {
        self._fields.0 = value;
        self
    }
}

impl<'a, S> UriBuilder<'a, S>
where
    S: uri_state::State,
    S::Uri: uri_state::IsUnset,
{
    /// Set the `uri` field (required)
    pub fn uri(
        mut self,
        value: impl Into<UriValue<S>>,
    ) -> UriBuilder<'a, uri_state::SetUri<S>> {
        self._fields.1 = Option::Some(value.into());
        UriBuilder {
            _state: PhantomData,
            _fields: self._fields,
            _lifetime: PhantomData,
        }
    }
}

impl<'a, S> UriBuilder<'a, S>
where
    S: uri_state::State,
    S::Uri: uri_state::IsSet,
{
    /// Build the final struct
    pub fn build(self) -> Uri<'a> {
        Uri {
            name: self._fields.0,
            uri: self._fields.1.unwrap(),
            extra_data: Default::default(),
        }
    }
    /// Build the final struct with custom extra_data
    pub fn build_with_data(self, extra_data: BTreeMap<SmolStr, Data<'a>>) -> Uri<'a> {
        Uri {
            name: self._fields.0,
            uri: self._fields.1.unwrap(),
            extra_data: Some(extra_data),
        }
    }
}